"'$item = Get-Item -LiteralPath $p
$raw = Get-Content -LiteralPath $p -Raw -Encoding UTF8
$data = $raw | ConvertFrom-Json
$agents = $data.agents
$pending = $data.pending
$schema = $data.schema
"schema=$schema"
"agents_type=$($agents.GetType().FullName)"
"pending_type=$(if ($null -eq $pending) { '"'<null>' } else { "'$pending.GetType().FullName })"
if ($agents -is [System.Array]) {
  "agents_is_array=true"
  "agents_count=$($agents.Count)"
} elseif ($agents -is [System.Collections.IDictionary]) {
  "agents_is_dict=true"
  "agents_count=$($agents.Count)"
} else {
  $props = @($agents.PSObject.Properties)
  "agents_psobject_props=$($props.Count)"
  "agents_count=$($props.Count)"
  "sample_agent_ids=$($props[0..4].Name -join '"',')\"
}
# pending count if present
if ("'$null -ne $pending) {
  if ($pending -is [System.Array]) { "pending_count=$($pending.Count)" }
  elseif ($pending.PSObject) { "pending_props=$($pending.PSObject.Properties.Count)" }
}'

