"C:\\Users\\hzq00\\.cache\\codex-runtimes\\codex-primary-runtime\\dependencies\\native\\powershell\\pwsh.exe" -Command '$raw = Get-Content -LiteralPath "E:'"\\codex-LOOP\\codex-loop-s-f2\\data\\lifecycle\\native_roster.json\" -Raw -Encoding UTF8
"'$data = $raw | ConvertFrom-Json
$run_close = 0; $run_open = 0; $term_close = 0; $models = @{}; $roles = @{}; $parents = @{}
$run_started_min = 1e99; $run_started_max = 0
$run_updated_min = 1e99; $run_updated_max = 0
$term_updated_max = 0
$key_mismatch = 0
foreach ($prop in $data.agents.PSObject.Properties) {
  $v = $prop.Value
  $roles[[string]$v.agent_role] = 1 + [int]$roles[[string]$v.agent_role]
  $models[[string]$v.model] = 1 + [int]$models[[string]$v.model]
  $parents[[string]$v.parent_session_id] = 1 + [int]$parents[[string]$v.parent_session_id]
  if ([string]$v.agent_id -ne [string]$prop.Name) { $key_mismatch++ }
  if ($v.status -eq '"'running') {
    if ("'$v.close_request_emitted) { $run_close++ } else { $run_open++ }
    $s = [double]$v.started_at; $u = [double]$v.updated_at
    if ($s -lt $run_started_min) { $run_started_min = $s }
    if ($s -gt $run_started_max) { $run_started_max = $s }
    if ($u -lt $run_updated_min) { $run_updated_min = $u }
    if ($u -gt $run_updated_max) { $run_updated_max = $u }
  } else {
    if ($v.close_request_emitted) { $term_close++ }
    $u = [double]$v.updated_at
    if ($u -gt $term_updated_max) { $term_updated_max = $u }
  }
}
"key_mismatch=$key_mismatch"
"running_close_request_true=$run_close"
"running_close_request_false=$run_open"
"terminal_close_request_true=$term_close"
"run_started_min=$run_started_min"
"run_started_max=$run_started_max"
"run_updated_min=$run_updated_min"
"run_updated_max=$run_updated_max"
"term_updated_max=$term_updated_max"
"parent_session_count=$($parents.Count)"
"role_hist:"
$roles.GetEnumerator() | Sort-Object Name | ForEach-Object { "  $($_.Name)=$($_.Value)" }
"model_hist:"
$models.GetEnumerator() | Sort-Object Name | ForEach-Object { "  $($_.Name)=$($_.Value)" }
"parent_hist:"
$parents.GetEnumerator() | Sort-Object Name | ForEach-Object { "  $($_.Name)=$($_.Value)" }
"top_updated_at=$($data.updated_at)"
"schema=$($data.schema)"
"pending_len=$(@($data.pending).Count)"'

